import{_ as o,C as r,o as s,c as d,j as a,a as t,b as l,w as n,E as h,a3 as p,a2 as c}from"./chunks/framework.CZqXuAiL.js";const w=JSON.parse('{"title":"The Hub Dashboard — Glacier Pack","description":"A tour of the Glacier Pack hub at /admin/glacier-pack — layout, rail groups, sub-tabs, the save round-trip, validation errors, and why the old addon admin pages are gone by design.","frontmatter":{"title":"The Hub Dashboard — Glacier Pack","description":"A tour of the Glacier Pack hub at /admin/glacier-pack — layout, rail groups, sub-tabs, the save round-trip, validation errors, and why the old addon admin pages are gone by design.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/user-guide/dashboard.md","filePath":"glacier-pack/user-guide/dashboard.md","lastUpdated":1785522036000}'),u={name:"glacier-pack/user-guide/dashboard.md"};function g(b,e,k,m,y,f){const i=r("Mermaid");return s(),d("div",null,[e[1]||(e[1]=a("h1",{id:"the-hub-dashboard",tabindex:"-1"},[t("The Hub Dashboard "),a("a",{class:"header-anchor",href:"#the-hub-dashboard","aria-label":'Permalink to "The Hub Dashboard"'},"​")],-1)),e[2]||(e[2]=a("p",null,[t("The hub at "),a("code",null,"/admin/glacier-pack"),t(" is the "),a("strong",null,"only admin surface"),t(" for the whole Glacier Addons family. It is a standalone, full-page admin UI — its own chrome, not AdminLTE — styled after the Glacier theme editor: near-black surfaces, a teal accent, and generous 14px radii. Everything you could ever do on an addon's original admin page happens here.")],-1)),e[3]||(e[3]=a("hr",null,null,-1)),e[4]||(e[4]=a("h2",{id:"layout",tabindex:"-1"},[t("Layout "),a("a",{class:"header-anchor",href:"#layout","aria-label":'Permalink to "Layout"'},"​")],-1)),(s(),l(p,null,{default:n(()=>[h(i,{id:"mermaid-10",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20TOP%5B%22gp-topbar%20%E2%80%94%20Glacier%20Pack%20brand%2C%20version%2C%20Back%20to%20Panel%22%5D%0A%20%20%20%20subgraph%20MAIN%5B%22gp-main%22%5D%0A%20%20%20%20%20%20%20%20RAIL%5B%22gp-rail%20%E2%80%94%20Basic%20Pack%20(10)%20%2F%20Advanced%20Pack%20(14)%3Cbr%2F%3Eicons%2C%20names%2C%20active%20state%2C%20keyboard%20navigation%22%5D%0A%20%20%20%20%20%20%20%20PANE%5B%22gp-content%20%E2%80%94%20pane%20header%2C%20banners%2C%3Cbr%2F%3Ethe%20active%20addon's%20full%20UI%22%5D%0A%20%20%20%20%20%20%20%20RAIL%20--%3E%20PANE%0A%20%20%20%20end%0A%20%20%20%20FOOT%5B%22gp-footer%20%E2%80%94%20addon%20count%2C%20linked%20count%22%5D%0A%20%20%20%20TOP%20--%3E%20MAIN%0A%20%20%20%20MAIN%20--%3E%20FOOT%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=c('<ul><li><strong>Topbar</strong> — the Glacier Pack brand mark and version on the left, a <strong>Back to Panel</strong> button on the right.</li><li><strong>Rail</strong> — every addon in the family, grouped under <strong>Basic Pack</strong> and <strong>Advanced Pack</strong> headers with counts. Each entry shows the addon&#39;s icon and name; the active entry is highlighted. <code>ArrowUp</code> / <code>ArrowDown</code> move through the rail when it has focus.</li><li><strong>Content</strong> — a pane header (addon name + one-line description), then the addon&#39;s complete management UI.</li><li><strong>Footer</strong> — total addon count and how many currently have a linked pane.</li></ul><p>The hub is <strong>root-admin only</strong>: the route group runs the standard admin middleware, and the controller performs a second explicit <code>root_admin</code> check, so no code path can ever render it for staff or regular users.</p><hr><h2 id="basic-vs-advanced-groups" tabindex="-1">Basic vs Advanced groups <a class="header-anchor" href="#basic-vs-advanced-groups" aria-label="Permalink to &quot;Basic vs Advanced groups&quot;">​</a></h2><p>The rail&#39;s two groups mirror the two packs. Basic pack addons are panel-operations tools (logs, alerts, uptime, file handling); Advanced pack addons are hosting workflows (backups, installers, delegation, imports). The grouping is presentational only — every pane works the same way regardless of pack.</p><hr><h2 id="panes-and-sub-tabs" tabindex="-1">Panes and sub-tabs <a class="header-anchor" href="#panes-and-sub-tabs" aria-label="Permalink to &quot;Panes and sub-tabs&quot;">​</a></h2><p>Clicking a rail entry opens the addon&#39;s <strong>main pane</strong> at <code>?a=&lt;slug&gt;</code>. Addons with multiple pages declare pill-style <strong>sub-tabs</strong> at the top of their pane — <code>?a=&lt;slug&gt;&amp;p=&lt;sub&gt;</code> renders the corresponding sub-page. An unknown or invalid <code>p</code> value falls back to the main pane gracefully.</p><p>Examples:</p><table tabindex="0"><thead><tr><th>Addon</th><th>Sub-tabs</th></tr></thead><tbody><tr><td>Resource Alerts</td><td>Overview · Rules · History · Settings</td></tr><tr><td>Backup Pro</td><td>Overview · Destinations · Backup Rules · Backups · Archives · Activity · Settings</td></tr><tr><td>Node Stats</td><td>Overview · Nodes · Capacity · Historical · Top Consumers · Reports · Settings</td></tr><tr><td>Permission Manager</td><td>Overview · Roles · Members · Audit Log</td></tr><tr><td>Subdomain Manager</td><td>Settings · Domains · Records</td></tr><tr><td>Node Status</td><td>Overview · Service Updates</td></tr><tr><td>Config Editor</td><td>Editor · Raw file</td></tr><tr><td>Server Importer</td><td>Overview · Run report</td></tr></tbody></table><p>The remaining 16 addons are single-pane — everything fits on one page.</p><hr><h2 id="how-panes-are-styled" tabindex="-1">How panes are styled <a class="header-anchor" href="#how-panes-are-styled" aria-label="Permalink to &quot;How panes are styled&quot;">​</a></h2><p>Panes follow two conventions, and you will see both:</p><ul><li><strong><code>.gp-native</code></strong> — the addon&#39;s original markup (boxes, tables, forms, buttons, badges, pagination, small-boxes), kept as-is and wrapped in a container the hub stylesheet re-themes to match. Tables, filters and pagination behave exactly like the addon&#39;s original pages.</li><li><strong><code>gp-*</code> components</strong> — shared hub building blocks (cards, buttons, switches, badges, range sliders) used for anything new.</li></ul><p>Either way, every control on a pane is real and functional — panes are not summaries or links out; they are the addon&#39;s entire admin UI.</p><hr><h2 id="saving-the-hub-round-trip" tabindex="-1">Saving: the <code>_hub</code> round-trip <a class="header-anchor" href="#saving-the-hub-round-trip" aria-label="Permalink to &quot;Saving: the `_hub` round-trip&quot;">​</a></h2><p>Every form on every pane posts to the addon&#39;s <strong>own existing endpoint</strong> — the hub adds no save logic of its own. A hidden <code>_hub</code> field carries the full return URL:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">input</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hidden&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_hub&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/admin/glacier-pack?a=</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slug&gt;&amp;p=</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sub&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>After the endpoint processes the request it redirects back to that URL, so you always land on the same pane you saved from. The <code>_hub</code> value is validated server-side — it must be a local <code>/admin/glacier-pack</code> path, anything else is rejected with 403.</p><ul><li><strong>Success</strong> — the pane reloads with <code>?saved=1</code> and a green <strong>Settings saved.</strong> banner that fades out after a few seconds.</li><li><strong>Validation failure</strong> — the redirect lands back on the hub automatically, and the hub shell renders the full error bag in a red callout above the pane, listing every rejected field.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Deep links are stable: <code>/admin/glacier-pack?a=backup-pro&amp;p=destinations</code> always opens that exact sub-tab — handy for runbooks and bookmarks.</p></div><hr><h2 id="how-addons-appear-once-installed" tabindex="-1">How addons appear once installed <a class="header-anchor" href="#how-addons-appear-once-installed" aria-label="Permalink to &quot;How addons appear once installed&quot;">​</a></h2><p>The rail renders from the hub&#39;s registry (<code>config/glacier-pack.php</code>), which lists all 24 addons. For each entry the hub checks whether the addon&#39;s pane partial exists on the panel:</p><ul><li><strong>Installed</strong> — the entry opens the addon&#39;s live pane.</li><li><strong>Not installed (or files missing)</strong> — the entry shows a small dot and opens a fallback card with the addon&#39;s description and, where applicable, a button to any native page that still exists.</li></ul><p>Install an addon and its pane lights up on the next page load — no hub reconfiguration is ever needed.</p><h2 id="the-old-admin-pages-are-gone-—-by-design" tabindex="-1">The old admin pages are gone — by design <a class="header-anchor" href="#the-old-admin-pages-are-gone-—-by-design" aria-label="Permalink to &quot;The old admin pages are gone — by design&quot;">​</a></h2><p>Before the hub, each addon injected its own sidebar link and shipped its own AdminLTE pages. The hub v2 contract removes both: addon installers no longer inject sidebar links (and actively clean up previously injected ones), and the addons&#39; original <code>GET /admin/&lt;addon&gt;</code> page routes and blades are deleted from the package. Only the <strong>action endpoints</strong> (POST/DELETE/API routes) remain — they are what hub forms post to.</p><p>Two deliberate exceptions:</p><ul><li><strong>Permission Manager&#39;s <code>/admin/staff</code></strong> is a <em>feature surface</em> for staff users, not a pack admin page — it stays, with its own middleware.</li><li>Client-facing UI (server pages, account area, login page) is untouched by the hub contract entirely.</li></ul><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./addons">Addons Guide →</a></strong> — what each of the 24 addons does and where it lives in the hub.</li><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every setting on every pane.</li><li><strong><a href="./../architecture/overview">Architecture →</a></strong> — the hub contract under the hood.</li></ul>',35))])}const E=o(u,[["render",g]]);export{w as __pageData,E as default};
